pm.test("Hash bloku zaczyna się od 0000 i zapisano dane bloku", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData).to.have.property("hash");
    pm.expect(jsonData.hash.startsWith("0000")).to.be.true;

    // Zapisujemy poprzedni hash jako prevHash, a bieżący jako lastHash
    pm.environment.set("prevHash", pm.environment.get("lastHash") || "");
    pm.environment.set("lastHash", jsonData.hash);
    pm.environment.set("minerId", jsonData.block.transactions[0].recipient);
});

