pm.test("Struktura JSON i zgodność previous_hash z poprzednim blokiem", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData).to.have.property("chain");
    pm.expect(jsonData).to.have.property("length");

    const lastBlock = jsonData.chain[jsonData.chain.length - 1];
    const prevHash = pm.environment.get("prevHash");

    if (prevHash) {
        pm.expect(lastBlock.previous_hash).to.eql(prevHash);
    }
});

